// MineBench: Choo-Choo Train
// Classic steam locomotive + tender + 2 passenger cars on track bed
// Oriented along +Z axis, centered at x=128, z~128
// Block types: stone, cobblestone, oak_planks, bricks, stone_bricks, grass_block,
//   dirt, sand, oak_log, oak_leaves, water, white_wool, black_wool, red_wool,
//   blue_wool, green_wool, yellow_wool, orange_wool, purple_wool, brown_wool,
//   gray_wool, glass, glowstone, iron_block, gold_block

// === CONSTANTS ===
const L = {};
L.xc = 128;
L.zfront = 80;
L.zboiler_start = 88;
L.zboiler_end = 130;
L.zcab_start = 132;
L.zcab_end = 158;
L.yboiler = 16;
L.boiler_r = 9;
L.yground = 2;
L.width = 30;

const T = {};
T.zstart = 160;
T.zend = 192;

const P = {};
P.zstart = 196;

// === HELPERS ===
function taper_cyl(x, y, z1, z2, r1, r2, type) {
  for (let z = z1; z <= z2; z++) {
    const t = (z - z1) / Math.max(1, z2 - z1);
    const r = r1 + (r2 - r1) * t;
    const r2sq = r * r;
    for (let dx = -Math.ceil(r); dx <= Math.ceil(r); dx++) {
      for (let dy = -Math.ceil(r); dy <= Math.ceil(r); dy++) {
        if (dx * dx + dy * dy <= r2sq) {
          block(x + dx, y + dy, z, type);
        }
      }
    }
  }
}

function wheel(x, y, z, r, rim_type, hub_type) {
  for (let dx = -r; dx <= r; dx++) {
    for (let dy = -r; dy <= r; dy++) {
      const d2 = dx * dx + dy * dy;
      if (d2 <= r * r) {
        if (d2 > (r - 1) * (r - 1)) {
          block(x + dx, y + dy, z, rim_type);
        } else if (d2 <= 1) {
          block(x + dx, y + dy, z, hub_type);
        } else {
          if (Math.abs(dx) === Math.abs(dy) || Math.abs(dx) < 2 || Math.abs(dy) < 2) {
            block(x + dx, y + dy, z, 'iron_block');
          } else {
            block(x + dx, y + dy, z, 'gray_wool');
          }
        }
      }
    }
  }
}

// === SCENE: TRACK BED ===
function build_track() {
  // Gravel / crushed stone
  for (let x = 112; x <= 144; x++) {
    for (let z = 60; z <= 240; z++) {
      block(x, 0, z, 'sand');
    }
  }
  // Dirt sub-base
  for (let x = 110; x <= 146; x++) {
    for (let z = 60; z <= 240; z++) {
      block(x, 0, z, 'dirt');
    }
  }
  // Rails
  for (let z = 60; z <= 240; z++) {
    block(120, 2, z, 'iron_block');
    block(136, 2, z, 'iron_block');
  }
  // Sleepers every 3 blocks
  for (let z = 60; z <= 240; z += 3) {
    box(117, 1, z, 139, 1, z, 'oak_log');
  }
  // Ground plane with grass
  for (let x = 80; x <= 176; x++) {
    for (let z = 40; z <= 260; z++) {
      if (x < 117 || x > 139 || z < 60 || z > 240) {
        block(x, 0, z, 'grass_block');
      }
    }
  }
  // Decorative bushes
  const bushes = [
    [105, 70], [155, 75], [100, 90], [160, 100],
    [108, 140], [152, 155], [103, 180], [158, 200],
    [110, 220], [150, 230], [95, 120], [165, 170],
    [106, 55], [154, 235]
  ];
  for (const [bx, bz] of bushes) {
    block(bx, 1, bz, 'oak_leaves');
    block(bx, 2, bz, 'oak_leaves');
    block(bx + 1, 1, bz, 'oak_leaves');
    block(bx - 1, 1, bz, 'oak_leaves');
    block(bx, 1, bz + 1, 'oak_leaves');
    block(bx, 1, bz - 1, 'oak_leaves');
  }
}

// === LOCOMOTIVE ===
function build_engine() {
  const cx = L.xc;
  const xL = cx - L.width / 2;
  const xR = cx + L.width / 2;

  // --- FIREBOX (rear of boiler) ---
  const fb_zS = 128;
  const fb_zE = 140;
  const fb_yB = L.yboiler - L.boiler_r + 2;
  const fb_yT = L.yboiler + L.boiler_r - 2;
  for (let z = fb_zS; z <= fb_zE; z++) {
    const t = (z - fb_zS) / (fb_zE - fb_zS);
    const xoff = Math.round(t * 2);
    box(xL - xoff, fb_yB, z, xR + xoff, fb_yT, z, 'bricks');
  }
  // Firebox glow
  for (let dx = -3; dx <= 3; dx++) {
    for (let dy = -3; dy <= 3; dy++) {
      if (dx * dx + dy * dy <= 9) {
        block(xR + 3, L.yboiler + dy, fb_zE, 'glowstone');
      }
    }
  }

  // --- MAIN BOILER ---
  for (let z = L.zboiler_start; z <= L.zboiler_end; z++) {
    const t = (z - L.zboiler_start) / (L.zboiler_end - L.zboiler_start);
    const r = L.boiler_r - Math.round(t * 1.5);
    const r2 = r * r;
    const ri2 = (r - 1) * (r - 1);
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        const d2 = dx * dx + dy * dy;
        if (d2 <= r2) {
          if (d2 > ri2) {
            block(cx + dx, L.yboiler + dy, z, 'iron_block');
          } else {
            block(cx + dx, L.yboiler + dy, z, 'black_wool');
          }
        }
      }
    }
  }

  // Boiler course bands
  for (let z = L.zboiler_start + 5; z <= L.zboiler_end - 5; z += 8) {
    const t = (z - L.zboiler_start) / (L.zboiler_end - L.zboiler_start);
    const r = L.boiler_r - Math.round(t * 1.5);
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (dx * dx + dy * dy <= r * r && dx * dx + dy * dy > (r - 1) * (r - 1)) {
          block(cx + dx, L.yboiler + dy, z, 'gray_wool');
        }
      }
    }
  }

  // --- SMOKESTACK ---
  const st_z = L.zfront + 5;
  const st_by = L.yboiler + L.boiler_r;
  const st_ty = st_by + 10;
  for (let y = st_by; y <= st_ty; y++) {
    const t = (y - st_by) / (st_ty - st_by);
    const r = 3 + Math.round(t * 2.5);
    for (let dx = -r; dx <= r; dx++) {
      for (let dz = -r; dz <= r; dz++) {
        if (dx * dx + dz * dz <= r * r) {
          const stripe = (y % 3 === 0);
          if (dx * dx + dz * dz > (r - 0.5) * (r - 0.5) || y === st_by || y === st_ty) {
            block(cx + dx, y, st_z + dz, stripe ? 'black_wool' : 'red_wool');
          }
        }
      }
    }
  }
  // Stack cap
  for (let dx = -5; dx <= 5; dx++) {
    for (let dz = -5; dz <= 5; dz++) {
      if (dx * dx + dz * dz <= 25) {
        block(cx + dx, st_ty, st_z + dz, 'iron_block');
      }
    }
  }

  // --- COWCATCHER ---
  for (let z = L.zfront; z <= L.zfront + 8; z++) {
    const p = (z - L.zfront) / 8;
    const w = Math.round(4 + p * 14);
    const h = Math.round(1 + p * 4);
    for (let dx = -w; dx <= w; dx++) {
      for (let dy = 0; dy < h; dy++) {
        block(cx + dx, dy, z, 'iron_block');
      }
    }
    if ((z - L.zfront) % 2 === 0) {
      for (let dy = 0; dy < h; dy++) {
        line(cx - w, dy, z, cx + w, dy, z, 'iron_block');
      }
    }
  }

  // --- HEADLIGHT ---
  const hl_y = L.yboiler;
  const hl_z = L.zfront + 2;
  for (let dx = -2; dx <= 2; dx++) {
    for (let dy = -2; dy <= 2; dy++) {
      if (dx * dx + dy * dy <= 4) {
        block(cx + dx, hl_y + dy, hl_z, 'glowstone');
      }
    }
  }
  for (let dx = -3; dx <= 3; dx++) {
    for (let dy = -3; dy <= 3; dy++) {
      if (dx * dx + dy * dy <= 9 && dx * dx + dy * dy > 4) {
        block(cx + dx, hl_y + dy, hl_z, 'iron_block');
      }
    }
  }

  // --- STEAM DOME ---
  const sd_z = 108;
  for (let dx = -3; dx <= 3; dx++) {
    for (let dy = 0; dy <= 4; dy++) {
      for (let dz = -3; dz <= 3; dz++) {
        if (dx * dx + dy * dy + dz * dz <= 13) {
          block(cx + dx, L.yboiler + L.boiler_r + dy, sd_z + dz, 'gold_block');
        }
      }
    }
  }
  block(cx, L.yboiler + L.boiler_r - 1, sd_z, 'iron_block');
  block(cx, L.yboiler + L.boiler_r - 2, sd_z, 'iron_block');

  // --- SAND DOME ---
  const sdn_z = 118;
  for (let dx = -2; dx <= 2; dx++) {
    for (let dy = 0; dy <= 3; dy++) {
      for (let dz = -2; dz <= 2; dz++) {
        if (dx * dx + dy * dy + dz * dz <= 8) {
          block(cx + dx, L.yboiler + L.boiler_r + dy, sdn_z + dz, 'brown_wool');
        }
      }
    }
  }

  // --- WHISTLE ---
  const wh_z = 100;
  for (let y = L.yboiler + L.boiler_r + 1; y <= L.yboiler + L.boiler_r + 3; y++) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        if (dx * dx + dz * dz <= 1) {
          block(cx + dx, y, wh_z + dz, 'gold_block');
        }
      }
    }
  }
  line(cx, L.yboiler + L.boiler_r + 2, wh_z, cx, L.yboiler + L.boiler_r + 2, 92, 'gold_block');

  // --- CAB ---
  const cab_xL = xL + 2;
  const cab_xR = xR - 2;
  const cab_zS = L.zcab_start;
  const cab_zE = L.zcab_end;

  box(cab_xL, L.yground, cab_zS, cab_xR, L.yground, cab_zE, 'oak_planks');
  box(cab_xL + 2, L.yground + 1, cab_zS + 2, cab_xR - 2, L.yground + 1, cab_zE - 2, 'oak_planks');

  // Walls with window cutouts
  for (let z = cab_zS; z <= cab_zE; z++) {
    for (let y = L.yground + 1; y <= 14; y++) {
      if (!(y >= 6 && y <= 10 && z >= cab_zS + 3 && z <= cab_zS + 12)) {
        block(cab_xL, y, z, 'bricks');
      }
      if (!(y >= 6 && y <= 10 && z >= cab_zS + 3 && z <= cab_zS + 12)) {
        block(cab_xR, y, z, 'bricks');
      }
    }
  }
  for (let y = L.yground + 1; y <= 14; y++) {
    for (let x = cab_xL; x <= cab_xR; x++) {
      if (!(y >= 6 && y <= 10)) {
        block(x, y, cab_zS, 'bricks');
      }
    }
  }
  for (let y = L.yground + 1; y <= 14; y++) {
    for (let x = cab_xL; x <= cab_xR; x++) {
      if (!(y >= 3 && y <= 5 && x >= cab_xL + 8 && x <= cab_xR - 8)) {
        block(x, y, cab_zE, 'bricks');
      }
    }
  }
  // Door frame
  box(cab_xL + 6, 2, cab_zE - 1, cab_xL + 6, 6, cab_zE + 1, 'iron_block');
  box(cab_xR - 6, 2, cab_zE - 1, cab_xR - 6, 6, cab_zE + 1, 'iron_block');
  box(cab_xL + 6, 6, cab_zE - 1, cab_xR - 6, 6, cab_zE + 1, 'iron_block');

  // Windows
  for (let y = 6; y <= 10; y++) {
    for (let x = cab_xL + 3; x <= cab_xR - 3; x++) {
      block(x, y, cab_zS, 'glass');
    }
  }
  for (let z = cab_zS + 4; z <= cab_zS + 11; z++) {
    for (let y = 6; y <= 10; y++) {
      block(cab_xL, y, z, 'glass');
      block(cab_xR, y, z, 'glass');
    }
  }

  // Arched roof
  const roof_mid = Math.round((cab_xL + cab_xR) / 2);
  for (let z = cab_zS - 1; z <= cab_zE + 1; z++) {
    for (let x = cab_xL - 1; x <= cab_xR + 1; x++) {
      const dist = Math.abs(x - roof_mid) / ((cab_xR - cab_xL) / 2);
      const arch = Math.round(3 * (1 - dist * dist));
      const ry = 15 + arch;
      box(x, ry, z, x, ry, z, 'bricks');
      if (arch > 0) {
        box(x, ry + 1, z, x, ry + 1, z, 'gray_wool');
      }
    }
  }

  // --- DRIVING WHEELS ---
  const wp = [98, 110, 122];
  for (let side = 0; side < 2; side++) {
    const wx = side === 0 ? xL - 1 : xR + 1;
    for (const wz of wp) {
      wheel(wx, L.yground, wz, 5, 'iron_block', 'gold_block');
      line(wx, L.yground, wz, cx, L.yground, wz, 'iron_block');
    }
  }

  // --- CONNECTING ROD ---
  const rod_y = 8;
  for (const wz of wp) {
    line(cx + L.width / 2 + 2, rod_y, wz, cx + L.width / 2 + 2, rod_y, wz + 3, 'iron_block');
  }
  line(cx + L.width / 2 + 2, rod_y, wp[0], cx + L.width / 2 + 2, rod_y, wp[2], 'iron_block');

  // --- PILOT LIGHTS ---
  block(cx - 3, 1, L.zfront + 4, 'glowstone');
  block(cx + 3, 1, L.zfront + 4, 'glowstone');

  // --- BELL ---
  const bell_z = 113;
  for (let dy = 0; dy <= 2; dy++) {
    const r = 2 + Math.round(dy * 0.5);
    for (let dx = -r; dx <= r; dx++) {
      for (let dz = -r; dz <= r; dz++) {
        if (dx * dx + dz * dz <= r * r) {
          block(cx + dx, L.yboiler + L.boiler_r + 1 + dy, bell_z + dz, 'gold_block');
        }
      }
    }
  }
  block(cx, L.yboiler + L.boiler_r + 1, bell_z, 'iron_block');
  block(cx, L.yboiler + L.boiler_r, bell_z, 'iron_block');

  // --- HANDRAILS ---
  for (let z = L.zfront + 10; z <= L.zcab_start; z++) {
    block(xL - 2, 10, z, 'iron_block');
    block(xR + 2, 10, z, 'iron_block');
  }
  for (let z = L.zfront + 10; z <= L.zcab_start; z += 4) {
    line(xL - 2, 10, z, xL - 2, 8, z, 'iron_block');
    line(xR + 2, 10, z, xR + 2, 8, z, 'iron_block');
  }

  // --- STEP PLATES ---
  for (let x = cab_xL - 2; x <= cab_xL + 2; x++) {
    box(x, 3, cab_zE + 1, x, 3, cab_zE + 3, 'iron_block');
  }
  for (let x = cab_xR - 2; x <= cab_xR + 2; x++) {
    box(x, 3, cab_zE + 1, x, 3, cab_zE + 3, 'iron_block');
  }

  // --- PISTON CYLINDER ---
  const piston_z = 92;
  for (let dx = -3; dx <= 3; dx++) {
    for (let dy = -2; dy <= 2; dy++) {
      if (dx * dx + dy * dy <= 9) {
        block(cx + dx, L.yboiler - L.boiler_r + 2 + dy, piston_z, 'iron_block');
      }
    }
  }
  line(cx, L.yboiler - L.boiler_r + 2, piston_z, cx, L.yboiler - L.boiler_r + 2, L.zfront + 6, 'iron_block');
}

// === TENDER ===
function build_tender() {
  const txL = 113;
  const txR = 143;
  const tzS = T.zstart;
  const tzE = T.zend;

  box(txL, L.yground, tzS, txR, L.yground, tzE, 'oak_planks');

  // Water tanks
  box(txL + 1, 3, tzS + 2, txL + 10, 8, tzE - 2, 'blue_wool');
  box(txR - 10, 3, tzS + 2, txR - 1, 8, tzE - 2, 'blue_wool');

  // Coal pile
  for (let x = txL + 11; x <= txR - 11; x++) {
    for (let z = tzS + 3; z <= tzE - 3; z++) {
      const nx = (x - txL - 11) / 20;
      const nz = (z - tzS - 3) / (tzE - tzS - 6);
      const h = Math.round(3 + 3 * Math.sin(nx * Math.PI) * Math.sin(nz * Math.PI));
      for (let y = 9; y <= 8 + h; y++) {
        block(x, y, z, 'black_wool');
      }
    }
  }

  // Walls
  box(txL, 9, tzS, txL, 11, tzE, 'iron_block');
  box(txR, 9, tzS, txR, 11, tzE, 'iron_block');
  box(txL, 9, tzS, txR, 11, tzS, 'iron_block');
  box(txL, 9, tzE, txR, 11, tzE, 'iron_block');

  // Roof
  box(txL - 1, 12, tzS - 1, txR + 1, 12, tzE + 1, 'gray_wool');

  // Coupler
  line(L.xc, 4, tzS - 2, L.xc, 4, tzS - 6, 'iron_block');
  block(L.xc, 4, tzS - 7, 'iron_block');
  block(L.xc + 1, 4, tzS - 7, 'iron_block');
  block(L.xc - 1, 4, tzS - 7, 'iron_block');

  // Tender wheels
  for (let side = 0; side < 2; side++) {
    const wx = side === 0 ? txL - 1 : txR + 1;
    for (const wz of [tzS + 5, tzS + 14, tzE - 6]) {
      wheel(wx, L.yground, wz, 3, 'iron_block', 'gold_block');
    }
  }
}

// === PASSENGER CAR ===
function build_passenger_car(zstart) {
  const pxL = 113;
  const pxR = 143;
  const plen = 30;
  const pzE = zstart + plen;

  box(pxL, 2, zstart, pxR, 2, pzE, 'iron_block');

  // Wheels (2 bogies, 2 per side)
  for (const wz of [zstart + 4, zstart + 22]) {
    for (let side = 0; side < 2; side++) {
      const wx = side === 0 ? pxL - 1 : pxR + 1;
      for (const woff of [-2, 2]) {
        wheel(wx, 2, wz + woff, 3, 'iron_block', 'gold_block');
      }
    }
  }

  const bb = 3, bm = 8, bt = 11;

  // Lower body
  box(pxL, bb, zstart, pxR, bm, zstart, 'white_wool');
  box(pxL, bb, pzE, pxR, bm, pzE, 'white_wool');
  box(pxL, bb, zstart, pxL, bm, pzE, 'white_wool');
  box(pxR, bb, zstart, pxR, bm, pzE, 'white_wool');

  // Upper body
  box(pxL, bm + 1, zstart, pxR, bt, zstart, 'brown_wool');
  box(pxL, bm + 1, pzE, pxR, bt, pzE, 'brown_wool');
  box(pxL, bm + 1, zstart, pxL, bt, pzE, 'brown_wool');
  box(pxR, bm + 1, zstart, pxR, bt, pzE, 'brown_wool');

  // Red stripe
  box(pxL, bm, zstart, pxR, bm, zstart, 'red_wool');
  box(pxL, bm, pzE, pxR, bm, pzE, 'red_wool');
  box(pxL, bm, zstart, pxL, bm, pzE, 'red_wool');
  box(pxR, bm, zstart, pxR, bm, pzE, 'red_wool');

  // Windows
  for (let z = zstart + 3; z <= pzE - 3; z += 5) {
    for (let y = bb + 1; y <= bm - 1; y++) {
      block(pxL, y, z, 'glass');
      block(pxR, y, z, 'glass');
    }
  }

  // Door
  const door_z = zstart + Math.round(plen / 2) - 2;
  box(pxL - 1, bb, door_z, pxL - 1, bm, door_z + 4, 'brown_wool');
  for (let y = bb + 1; y <= bm - 1; y++) {
    block(pxL, y, door_z, 'glass');
    block(pxL, y, door_z + 4, 'glass');
  }

  // Roof
  box(pxL - 2, bt + 1, zstart - 1, pxR + 2, bt + 1, pzE + 1, 'gray_wool');
  box(pxL, bt + 2, zstart, pxR, bt + 2, pzE, 'stone_bricks');

  // Bottom trim
  box(pxL, bb - 1, zstart, pxR, bb - 1, zstart, 'red_wool');
  box(pxL, bb - 1, pzE, pxR, bb - 1, pzE, 'red_wool');
  box(pxL, bb - 1, zstart, pxL, bb - 1, pzE, 'red_wool');
  box(pxR, bb - 1, zstart, pxR, bb - 1, pzE, 'red_wool');

  // Coupler
  line(L.xc, 3, zstart - 1, L.xc, 3, zstart - 5, 'iron_block');
  block(L.xc, 3, zstart - 6, 'iron_block');
}

// === BUILD IT ALL ===
build_track();
build_engine();
build_tender();
build_passenger_car(P.zstart);
build_passenger_car(P.zstart + 36);
